// A missed call becomes a text conversation within seconds, and the
// appointment gets recovered instead of lost to whoever the caller rings next.
//
// GHL webhook payloads are not stable enough to trust field names, so this
// reads defensively: several candidate shapes for each fact, never failing
// the run because a webhook arrived nested differently than last week.

const body = $input.first().json;
const flat = (v) => (typeof v === 'object' && v !== null ? v : {});
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

const call = flat(body.call);
const contact = flat(body.contact);
const location = flat(body.location);

const rawPhone = str(body.phone || body.from || body.fromNumber || body.callerNumber ||
  call.phone || call.from || contact.phone || contact.mobilePhone || '');
const phone = rawPhone.replace(/[^+0-9]/g, '');
const contact_id = str(body.contactId || body.contact_id || contact.id || contact.contactId);
const location_id = str(body.locationId || body.location_id || location.id || location.locationId);
const call_ref = str(body.callId || body.call_id || body.id || call.id || '');
const tags = Array.isArray(contact.tags) ? contact.tags.map(str) : [];

return [{
  json: {
    phone,
    contact_id,
    location_id,
    call_ref,
    tags,
    raw_phone: rawPhone,
    received_at: new Date().toISOString()
  }
}];

// The decision, in one place, so the execution log reads like a policy
// rather than a coincidence of node wiring.
//
// Order matters: the most permanent reasons (already talking to this person)
// are checked before the transient ones (it is 9pm).
//
// Tuning knobs live here as literals matching the workflow README defaults:
//   quiet hours               20:00-08:00  (QUIET_HOURS_START / QUIET_HOURS_END)
//   max rescues per contact  1            (MAX_RESCUE_PER_CONTACT_PER_DAY)
// Change them here if this n8n instance sets different values.

const ctx = $input.first().json;
const parsed = $('Parse the webhook').first().json;

const MAX_PER_DAY = 1;
const quietStart = 20 * 60;         // 20:00, location time
const quietEnd = 8 * 60;            // 08:00, location time
const tz = ctx.timezone || 'America/New_York';

const now = new Date();
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: tz, hour: 'numeric', minute: 'numeric', hour12: false
}).formatToParts(now);
const hour = Number(parts.find(p => p.type === 'hour').value);
const minute = Number(parts.find(p => p.type === 'minute').value);
const mins = hour * 60 + minute;
const inQuietHours = quietEnd > quietStart
  ? mins >= quietStart && mins < quietEnd
  : mins >= quietStart || mins < quietEnd;

const OPT_OUT_TAGS = ['do-not-contact', 'no-texts', 'opt-out'];
const optedOut = parsed.tags.some(t => OPT_OUT_TAGS.includes(String(t).toLowerCase()));

let should_send = true;
let reason = '';
if (Number(ctx.open_calls) > 0) { should_send = false; reason = 'already in an open conversation'; }
else if (inQuietHours) { should_send = false; reason = 'quiet hours (' + tz + ')'; }
else if (optedOut) { should_send = false; reason = 'contact opted out of texts'; }
else if (Number(ctx.inbound_today) >= MAX_PER_DAY) { should_send = false; reason = 'daily rescue limit reached for this contact'; }

return [{
  json: {
    should_send,
    reason,
    phone: parsed.phone,
    contact_id: parsed.contact_id,
    location_id: parsed.location_id,
    call_ref: parsed.call_ref,
    business_name: ctx.business_name,
    timezone: tz,
    in_quiet_hours: inQuietHours,
    open_calls: Number(ctx.open_calls),
    inbound_today: Number(ctx.inbound_today),
    opted_out: optedOut
  }
}];
